// Emits the Go artifact: zz_catalog.gen.go for package `domain`.
//
// Design: the generated file is SELF-CONTAINED. It declares its own
// fieldDef/attrKind types, the kind constants, the per-type field maps, and the
// functions (fieldsForType, CatalogKeys, FilterByType, ValidateAttributes,
// validateField). It also emits Russian display
// labels for export pipelines: PropertyTypeLabel (type label),
// AttributeFieldLabel (field label, type-scoped), and AttributeEnumLabel (enum
// option label, type-scoped), all sourced from catalog.json.
//
// Integration note: zz_catalog.gen.go is the single implementation of the
// catalog symbols in package `domain` (the migration step 1.4b removed the
// hand-written duplicates from attributes.go).
//
// To verify the generated code in isolation we copy it to a temp dir, rename the
// package, and add stubs for PropertyType/Attributes/PropertyTypeXxx constants —
// see `verifyGoIsolated` in generate.mjs.

import {
  TYPE_ORDER,
  TYPE_ALIASES,
  aliasOf,
  fieldsFor,
  enumOptionKeys,
} from './model.mjs';

const HEADER = `// Code generated by tools/property-attributes/generate.mjs from catalog.json. DO NOT EDIT.
//
// zz_catalog.gen.go — сгенерировано из tools/property-attributes/catalog.json.
// НЕ редактировать вручную. Чтобы регенерировать:
//
//	cd tools/property-attributes && node generate.mjs
//
// (или из корня монорепо: npm --prefix tools/property-attributes run generate)
//
// Самодостаточный модуль: объявляет fieldDef/attrKind, карты полей, функции
// валидации (только минимумы — потолков нет, решение владельца 23.10.2026;
// кросс-правила сняты) и функции русских подписей (PropertyTypeLabel,
// AttributeFieldLabel, AttributeEnumLabel) для экспорта (XLSX и т.п.).
`;

function emitFieldDef(typeKey, catalog) {
  const entries = fieldsFor(catalog, typeKey);
  const varName = typeKey + 'Fields';
  const lines = [];
  for (const { key, def } of entries) {
    const labelExpr = `, label: ${JSON.stringify(def.label)}`;
    let val;
    switch (def.kind) {
      case 'enum': {
        const opts = enumOptionKeys(def).map((o) => JSON.stringify(o)).join(', ');
        const labelMap = emitEnumLabelsMap(def);
        val = `kind: kindEnum, enumVals: []string{${opts}}, enumLabels: ${labelMap}`;
        break;
      }
      case 'number':
        val = 'kind: kindNumber';
        break;
      case 'integer':
        val = 'kind: kindInteger';
        break;
      case 'string':
        val = `kind: kindString, maxLen: ${def.maxLen}`;
        break;
      default:
        throw new Error(`unknown kind for field ${key}: ${def.kind}`);
    }
    lines.push(`\t\t${JSON.stringify(key)}: { ${val}${labelExpr} },`);
  }
  return `\t${varName} = map[string]fieldDef{
${lines.join('\n')}
\t}`;
}

// Emit a Go map[string]string literal for an enum field's option labels, in the
// same order as options appear in catalog.json (first-seen label wins, matching
// mergedEnumOptions). Example output:
//   map[string]string{"combined": "Совмещенный", "separate": "Раздельный"}
function emitEnumLabelsMap(fieldDef) {
  const entries = fieldDef.options.map(
    (o) => `${JSON.stringify(o.key)}: ${JSON.stringify(o.label)}`,
  );
  return `map[string]string{${entries.join(', ')}}`;
}

function emitFieldMaps(catalog) {
  // Declare the primary maps (apartment, room, house, office, warehouse, garage,
  // parking, land) and alias assignments (commercial = office).
  const primaries = TYPE_ORDER.filter((t) => !TYPE_ALIASES[t]);
  const blocks = primaries.map((t) => emitFieldDef(t, catalog));
  // Alias assignments: comment + assignment, matching Go hand-written style.
  const aliasLines = [];
  for (const [alias, primary] of Object.entries(TYPE_ALIASES)) {
    aliasLines.push(
      `\t// ${alias}Fields mirrors ${primary}Fields (the "${alias}" type shares the ${primary} field set).`,
      `\t${alias}Fields = ${primary}Fields`,
    );
  }
  return `var (
${blocks.join('\n\n')}
${aliasLines.join('\n')}
)`;
}

function emitFieldsForType() {
  // apartment/apartments share the same map (both = apartmentFields).
  return `// fieldsForType returns the catalog field map for the given property type.
// All eleven property types are covered. Returns nil only for an unknown type.
func fieldsForType(t PropertyType) map[string]fieldDef {
\tswitch t {
\tcase PropertyTypeApartment, PropertyTypeApartments:
\t\treturn apartmentFields
\tcase PropertyTypeStudio:
\t\treturn studioFields
\tcase PropertyTypeRoom:
\t\treturn roomFields
\tcase PropertyTypeHouse:
\t\treturn houseFields
\tcase PropertyTypeOffice:
\t\treturn officeFields
\tcase PropertyTypeCommercial:
\t\treturn commercialFields
\tcase PropertyTypeWarehouse:
\t\treturn warehouseFields
\tcase PropertyTypeGarage:
\t\treturn garageFields
\tcase PropertyTypeParking:
\t\treturn parkingFields
\tcase PropertyTypeLand:
\t\treturn landFields
\tdefault:
\t\treturn nil
\t}
}`;
}

function emitCatalogKeys() {
  return `// CatalogKeys returns the set of catalog attribute keys for the given property
// type. Returns nil for an unknown type.
func CatalogKeys(propType PropertyType) []string {
\tfields := fieldsForType(propType)
\tif fields == nil {
\t\treturn nil
\t}
\tkeys := make([]string, 0, len(fields))
\tfor k := range fields {
\t\tkeys = append(keys, k)
\t}
\tsort.Strings(keys)
\treturn keys
}`;
}

function emitFilterByType() {
  return `// FilterByType returns a copy of attrs containing only keys that belong to the
// catalog of the given property type. Unknown keys are silently dropped. This
// implements the "current type determines the meaning of stored keys" read
// semantics: when the type changes, keys of the old type become inert.
func (a Attributes) FilterByType(propType PropertyType) Attributes {
\tfields := fieldsForType(propType)
\tout := make(Attributes, len(a))
\tfor k, v := range a {
\t\tif _, ok := fields[k]; ok {
\t\t\tout[k] = v
\t\t}
\t}
\treturn out
}`;
}

function emitValidateAttributes() {
  return `// ValidateAttributes validates the given attributes against the catalog for the
// given property type. Only keys belonging to the catalog of the current type
// are accepted; unknown keys and null values are rejected. Numeric ranges,
// enum membership are checked; upper bounds and cross-field rules are gone
// (решение владельца 23.10.2026). All eleven property types
// are supported.
func ValidateAttributes(propType PropertyType, attrs Attributes) ValidationResult {
\tvar res ValidationResult
\tfields := fieldsForType(propType)

\t// Unsupported type: every key is unknown. Empty attrs => valid (vacuous).
\tif fields == nil {
\t\tif len(attrs) == 0 {
\t\t\treturn res
\t\t}
\t\tkeys := make([]string, 0, len(attrs))
\t\tfor k := range attrs {
\t\t\tkeys = append(keys, k)
\t\t}
\t\tsort.Strings(keys)
\t\tfor _, k := range keys {
\t\t\tres.Errors = append(res.Errors, AttributeValidationError{
\t\t\t\tField:  k,
\t\t\t\tReason: fmt.Sprintf("unknown attribute for property type %s", propType),
\t\t\t})
\t\t}
\t\treturn res
\t}

\t// Deterministic ordering: sorted slice of catalog keys, then unknown keys.
\tcatKeys := make([]string, 0, len(fields))
\tfor k := range fields {
\t\tcatKeys = append(catKeys, k)
\t}
\tsort.Strings(catKeys)

\t// Validate present catalog fields first.
\tfor _, k := range catKeys {
\t\tv, present := attrs[k]
\t\tif !present {
\t\t\tcontinue
\t\t}
\t\tif v == nil {
\t\t\tres.Errors = append(res.Errors, AttributeValidationError{
\t\t\t\tField:  k,
\t\t\t\tReason: "attribute value must not be null",
\t\t\t})
\t\t\tcontinue
\t\t}
\t\tdef := fields[k]
\t\tif reason := validateField(def, v); reason != "" {
\t\t\tres.Errors = append(res.Errors, AttributeValidationError{
\t\t\t\tField:  k,
\t\t\t\tReason: reason,
\t\t\t})
\t\t}
\t}

\t// Report unknown keys (present in attrs but not in the catalog) in sorted order.
\tunknownKeys := make([]string, 0)
\tfor k := range attrs {
\t\tif _, ok := fields[k]; !ok {
\t\t\tunknownKeys = append(unknownKeys, k)
\t\t}
\t}
\tsort.Strings(unknownKeys)
\tfor _, k := range unknownKeys {
\t\tres.Errors = append(res.Errors, AttributeValidationError{
\t\t\tField:  k,
\t\t\tReason: fmt.Sprintf("unknown attribute for property type %s", propType),
\t\t})
\t}

\treturn res
}`;
}

function emitValidateField() {
  return `// validateField checks a single present field against its definition and returns
// a non-empty reason string on failure, or "" when valid.
func validateField(def fieldDef, v any) string {
\tswitch def.kind {
\tcase kindNumber:
\t\tif _, ok := v.(float64); !ok {
\t\t\treturn "expected a number"
\t\t}
\tcase kindInteger:
\t\tf, ok := v.(float64)
\t\tif !ok {
\t\t\treturn "expected an integer"
\t\t}
\t\tif f != float64(int64(f)) {
\t\t\treturn "expected an integer"
\t\t}
\tcase kindString:
\t\ts, ok := v.(string)
\t\tif !ok {
\t\t\treturn "expected a string"
\t\t}
\t\tif utf8.RuneCountInString(s) > def.maxLen {
\t\t\treturn fmt.Sprintf("must be at most %d characters", def.maxLen)
\t\t}
\tcase kindEnum:
\t\ts, ok := v.(string)
\t\tif !ok {
\t\t\treturn "expected a string"
\t\t}
\t\tif !slices.Contains(def.enumVals, s) {
\t\t\treturn fmt.Sprintf("must be one of %v", def.enumVals)
\t\t}
\t}
\treturn ""
}`;
}

// Emit PropertyTypeLabel: a switch over all ten PropertyType constants
// returning the Russian display label from catalog.json types.<key>.label.
// Unknown types return "" so callers (e.g. XLSX export) never panic on bad data.
function emitPropertyTypeLabel(catalog) {
  const arms = TYPE_ORDER.map(
    (t) =>
      `\tcase ${propertyTypeConst(t)}:\n\t\treturn ${JSON.stringify(catalog.types[t].label)}`,
  ).join('\n');
  return `// PropertyTypeLabel returns the Russian display label for a property type
// (e.g. PropertyTypeApartment -> "Квартира"), sourced from catalog.json
// types.<key>.label. Returns an empty string for an unknown type so export
// pipelines degrade gracefully instead of crashing on unexpected values.
func PropertyTypeLabel(propType PropertyType) string {
\tswitch propType {
${arms}
\tdefault:
\t\treturn ""
\t}
}`;
}

// Emit AttributeFieldLabel: looks up fieldKey in fieldsForType(propType) and
// returns its Russian label. Returns "" when the type is unknown or the field
// is not part of that type's catalog (so a field shared across types resolves
// per-type, and a field absent from the type resolves to empty).
function emitAttributeFieldLabel() {
  return `// AttributeFieldLabel returns the Russian display label for a catalog field
// in the context of a specific property type (e.g. for PropertyTypeApartment,
// "rooms" -> "Комнаты"). The lookup is type-scoped because the same field key
// (e.g. "bathroom") can carry different option sets per type. Returns an empty
// string when the type is unknown or the field is not part of that type's
// catalog.
func AttributeFieldLabel(propType PropertyType, fieldKey string) string {
\tfields := fieldsForType(propType)
\tif fields == nil {
\t\treturn ""
\t}
\treturn fields[fieldKey].label
}`;
}

// Emit AttributeEnumLabel: looks up the Russian label for an enum option key on
// a field of a specific property type. Returns "" when the type, field, or
// option is unknown, or when the field is not an enum.
function emitAttributeEnumLabel() {
  return `// AttributeEnumLabel returns the Russian display label for an enum option
// value of a catalog field in the context of a specific property type (e.g. for
// PropertyTypeApartment, field "bathroom", option "combined" -> "Совмещенный").
// Returns an empty string when the type, field, or option is unknown, or when
// the field is not an enum.
func AttributeEnumLabel(propType PropertyType, fieldKey, optionKey string) string {
\tfields := fieldsForType(propType)
\tif fields == nil {
\t\treturn ""
\t}
\tdef, ok := fields[fieldKey]
\tif !ok || def.kind != kindEnum {
\t\treturn ""
\t}
\treturn def.enumLabels[optionKey]
}`;
}

function propertyTypeConst(typeKey) {
  return 'PropertyType' + typeKey.charAt(0).toUpperCase() + typeKey.slice(1);
}

export function emitGo(catalog) {
  const parts = [
    HEADER,
    `package domain

import (
\t"fmt"
\t"slices"
\t"sort"
\t"unicode/utf8"
)

// attrKind classifies a catalog field's value type.
type attrKind int

const (
\tkindNumber attrKind = iota
\tkindInteger
\tkindString
\tkindEnum
)

// fieldDef internally describes each catalog field.
type fieldDef struct {
	kind       attrKind
	maxLen     int                // for kindString
	enumVals   []string           // for kindEnum (stored values, e.g. "studio")
	label      string             // Russian display label for the field (from catalog.json)
	enumLabels map[string]string  // for kindEnum: stored value -> Russian label (from catalog.json)
}
`,

    emitFieldMaps(catalog),
    emitFieldsForType(),
    emitCatalogKeys(),
    emitFilterByType(),
    emitValidateAttributes(),
    emitValidateField(),
    emitPropertyTypeLabel(catalog),
    emitAttributeFieldLabel(),
    emitAttributeEnumLabel(),
  ];
  return parts.join('\n\n') + '\n';
}
